function validate([words]) {
  if (!Array.isArray(words) || words.length < 3 || words.length > 100) return 'words needs 3 to 100 strings.';
  const n = words[0].length;
  if (n < 2 || n > 20) return 'Each string has 2 to 20 letters.';
  if (words.some(w => typeof w !== 'string' || w.length !== n)) return 'All strings must have the same length.';
  if (words.some(w => !/^[a-z]+$/.test(w))) return 'Strings contain only lowercase letters.';
  const count = new Map();
  for (const w of words) {
    const key = [...w].slice(1).map((c, j) => c.charCodeAt(0) - w.charCodeAt(j)).join(',');
    count.set(key, (count.get(key) || 0) + 1);
  }
  if (count.size !== 2 || ![...count.values()].includes(1)) return 'Exactly one string must have a different gap list.';
  return null;
}

