function oddString(words) {
  const count = new Map();
  const keys = [];
  for (const word of words) {
    const gaps = [];
    for (let j = 0; j + 1 < word.length; j++) {
      gaps.push(word.charCodeAt(j + 1) - word.charCodeAt(j));
    }
    const key = gaps.join(',');
    keys.push(key);
    count.set(key, (count.get(key) || 0) + 1);
  }
  for (let i = 0; i < words.length; i++) {
    if (count.get(keys[i]) === 1) {
      return words[i];
    }
  }
  return '';
}

