function oddString(words) {
  const same = (a, b) => {
    for (let j = 1; j < a.length; j++) if (a.charCodeAt(j) - a.charCodeAt(j - 1) !== b.charCodeAt(j) - b.charCodeAt(j - 1)) return false;
    return true;
  };
  for (let i = 0; i < words.length; i++) {
    let matches = 0;
    for (let k = 0; k < words.length; k++) if (k !== i && same(words[i], words[k])) matches++;
    if (matches === 0) return words[i];
  }
  return null;
}

