function generate(rand, size) {
  const m = size === 'large' ? 100 : 3 + Math.floor(rand() * 5);
  const n = size === 'large' ? 20 : 2 + Math.floor(rand() * 3);
  const letters = (k) => {
    // A narrow window of letters leaves room to shift the word and keep its gap list.
    const width = 1 + Math.floor(rand() * k);
    const start = Math.floor(rand() * (27 - width));
    return Array.from({ length: n }, () => start + Math.floor(rand() * width));
  };
  const gapsOf = (codes) => codes.slice(1).map((c, j) => c - codes[j]).join(',');
  const base = letters(size === 'large' ? 8 : 26);
  const low = Math.min(...base), high = Math.max(...base);
  const toWord = (codes) => codes.map(c => String.fromCharCode(97 + c)).join('');
  const words = [];
  for (let i = 0; i < m - 1; i++) {
    const shift = -low + Math.floor(rand() * (26 - (high - low)));
    words.push(toWord(base.map(c => c + shift)));
  }
  let odd;
  do odd = letters(26); while (gapsOf(odd) === gapsOf(base));
  words.splice(Math.floor(rand() * m), 0, toWord(odd));
  return [words];
}
